(() => {
'use strict';
const $=s=>document.querySelector(s),vocab=window.VOCAB,canvas=$('#board'),ctx=canvas.getContext('2d');
const turnCard=$('.turn-card');function setInline(){if(!turnCard.open||turnCard.matches(':modal')){if(turnCard.open)turnCard.close();turnCard.show()}}function setModal(){if(turnCard.open)turnCard.close();turnCard.showModal()}turnCard.addEventListener('cancel',e=>e.preventDefault());
const teams=[{name:'Red',animal:'Cat',emoji:'🐱',color:'#ce5666',fur:'#f8dfb3'},{name:'Blue',animal:'Dog',emoji:'🐶',color:'#4c85c9',fur:'#d6b396'},{name:'Yellow',animal:'Chicken',emoji:'🐔',color:'#ae811c',fur:'#fff1c9'},{name:'Green',animal:'Pig',emoji:'🐷',color:'#429b76',fur:'#efb5c2'}].map(t=>({...t,score:0,pos:0,point:[0,0]}));
const path=[];for(let x=0;x<5;x++)path.push([x*3,0]);for(let z=0;z<5;z++)path.push([15,z*3]);for(let x=5;x>0;x--)path.push([x*3,15]);for(let z=5;z>0;z--)path.push([0,z*3]);
const CORNER_TYPES={0:'start',5:'bonus',10:'jail',15:'penalty'};
let vc=0;const vocabIndexAt=path.map((_,i)=>i%5===0?null:vc++);
const isVocabTile=i=>vocabIndexAt[i]!==null;
const tileLabel=pos=>{const type=CORNER_TYPES[pos];return type?CORNER_INFO[type].label:'Tile '+(vocabIndexAt[pos]+1)};
const CORNER_INFO={start:{icon:'🚩',label:'START',bg:'#a8d8b0'},bonus:{icon:'⭐',label:'+10 POINTS',bg:'#f4d35e'},jail:{icon:null,label:'JAIL',bg:'#8891a0'},penalty:{icon:'⚠️',label:'-10 POINTS',bg:'#e2867a'}};
let turn=0,round=1,phase='ready',choices=[],correctIndex=-1,lastRoll=0,hop=0,epoch=0,seen=new Set();
let width=0,height=0,unit=1,ox=0,oy=0;
const DICE=['⚀','⚁','⚂','⚃','⚄','⚅'];
const random=n=>{const a=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%n};
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=random(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function project(x,z,y=0){return [ox+(x-z)*unit,oy+(x+z)*unit*.51-y*unit]}
function polygon(points,color,stroke){ctx.beginPath();points.forEach((p,i)=>{const q=project(...p);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.7;ctx.stroke()}}
function box(x,z,y,w,d,h,top,left,right){polygon([[x,z,y+h],[x+w,z,y+h],[x+w,z+d,y+h],[x,z+d,y+h]],top);polygon([[x,z+d,y],[x+w,z+d,y],[x+w,z+d,y+h],[x,z+d,y+h]],left);polygon([[x+w,z,y],[x+w,z+d,y],[x+w,z+d,y+h],[x+w,z,y+h]],right)}
function tree(x,z,s=1){box(x-.08,z-.08,.08,.16,.16,.6*s,'#b49a86','#b49a86','#987f6c');let y=.5;for(let i=0;i<2;i++){let r=(.5-i*.13)*s;polygon([[x-r,z-r,y],[x+r,z-r,y],[x,z,y+1*s]],'#9fc6ac');polygon([[x+r,z-r,y],[x+r,z+r,y],[x,z,y+1*s]],'#75ac91');polygon([[x+r,z+r,y],[x-r,z+r,y],[x,z,y+1*s]],'#87bba0');y+=.5*s}}
function house(x,z,s=1,color='#d8b7ca'){box(x,z,.06,s,s,s*.7,'#f7ebd7','#f6e6cf','#deceb9');polygon([[x-.1,z-.1,.7*s],[x+s+.1,z-.1,.7*s],[x+s/2,z-.1,1.25*s]],color);polygon([[x+s+.1,z-.1,.7*s],[x+s+.1,z+s+.1,.7*s],[x+s/2,z+s+.1,1.25*s],[x+s/2,z-.1,1.25*s]],'#ab88b4');polygon([[x-.1,z-.1,.7*s],[x+s/2,z-.1,1.25*s],[x+s/2,z+s+.1,1.25*s],[x-.1,z+s+.1,.7*s]],color);box(x+s*.36,z+s+.005,.06,s*.26,.01,s*.4,'#a88d84','#a88d84','#a88d84')}
function jailIcon(cx,cy,s){ctx.save();const barW=s*.13,gap=(s-4*barW)/3,frameW=s*.9;ctx.fillStyle='#181818';for(let k=0;k<4;k++)ctx.fillRect(cx-frameW/2+k*(barW+gap),cy-s/2,barW,s);ctx.fillRect(cx-frameW/2,cy-s/2,frameW,s*.13);ctx.fillRect(cx-frameW/2,cy+s*.5-s*.13,frameW,s*.13);const lockW=s*.42,lockH=s*.34,lx=cx-lockW/2,ly=cy-lockH*.05;ctx.beginPath();if(ctx.roundRect)ctx.roundRect(lx,ly,lockW,lockH,lockW*.2);else ctx.rect(lx,ly,lockW,lockH);ctx.fillStyle='#181818';ctx.fill();ctx.strokeStyle='#181818';ctx.lineWidth=s*.065;ctx.beginPath();ctx.arc(cx,ly,lockW*.3,Math.PI,0);ctx.stroke();ctx.fillStyle='#f3efe4';ctx.beginPath();ctx.arc(cx,ly+lockH*.42,lockH*.13,0,Math.PI*2);ctx.fill();ctx.fillRect(cx-lockH*.05,ly+lockH*.42,lockH*.1,lockH*.4);ctx.restore()}
function animal(t,i){const x=t.point[0]+.4+(i%2)*1.05,z=t.point[1]+.48+Math.floor(i/2)*1.05,y=.47+(i===turn?hop:0);box(x-.08,z-.08,y,.8,.8,.1,t.color,t.color,t.color);box(x+.05,z+.05,y+.1,.55,.5,.48,t.fur,t.fur,t.fur);box(x+.01,z+.01,y+.54,.62,.58,.43,t.fur,t.fur,t.fur);
if(i===0||i===3){polygon([[x+.02,z+.57,y+.97],[x+.2,z+.57,y+.97],[x+.02,z+.57,y+1.2]],i===0?'#eabca8':'#d98d9f');polygon([[x+.43,z+.57,y+.97],[x+.62,z+.57,y+.97],[x+.62,z+.57,y+1.2]],i===0?'#eabca8':'#d98d9f')}
if(i===1){box(x-.11,z+.5,y+.51,.2,.29,.45,'#9f7967','#9f7967','#8e6857');box(x+.57,z+.55,y+.51,.2,.27,.45,'#9f7967','#9f7967','#8e6857')}
if(i===2){box(x+.17,z+.47,y+.97,.22,.2,.22,'#dd727a','#dc6470','#c7505b');polygon([[x+.24,z-.01,y+.68],[x+.42,z-.01,y+.68],[x+.33,z-.28,y+.59]],'#e6b547')}
if(i===3)box(x+.15,z+.02,y+.59,.32,.13,.18,'#dd90a3','#dd90a3','#c67b8f');
const p=project(x+.31,z-.01,y+.8);ctx.fillStyle='#574455';ctx.beginPath();ctx.arc(p[0]-.12*unit,p[1]+.05*unit,.035*unit,0,Math.PI*2);ctx.arc(p[0]+.11*unit,p[1]-.07*unit,.035*unit,0,Math.PI*2);ctx.fill();if(i===turn){const q=project(x+.3,z+.3,y+1.65);ctx.fillStyle=t.color;ctx.font=`bold ${Math.max(13,unit*.39)}px Segoe UI`;ctx.textAlign='center';ctx.fillText('▼',q[0],q[1])}}
function container(x,z,y,c){box(x,z,y,1.4,.68,.55,c,c,'#789296');for(let k=.2;k<1.3;k+=.25)box(x+k,z+.69,y+.06,.03,.015,.42,'#ffffff55','#ffffff55','#ffffff55')}
function harbor(){box(3.15,3.15,.02,8.7,8.7,.06,'#a5dce0','#93ced5','#93ced5');for(let k=0;k<5;k++){polygon([[4+k*.8,8.7,.10],[4.6+k*.8,8.7,.10],[4.9+k*.8,8.85,.10],[4.3+k*.8,8.85,.10]],'#d0eeea')}
box(7.5,3.2,.1,4.3,3.7,.3,'#e5e0ce','#ccc8b8','#b6bbad');house(9.2,3.5,1.5,'#aebbd3');container(7.8,5.5,.45,'#b6a4d6');container(9.4,5.5,.45,'#e4b38d');container(9.4,5.5,1,'#8dbdba');
// Cargo ship with faceted bow and stacked containers.
polygon([[4.1,4.4,.1],[5.1,3.9,.1],[6.5,4.4,.1],[6.5,8,.1],[5.3,8.6,.1],[4.1,8,.1]],'#637f9f');box(4.2,4.5,.1,2.15,3.35,.45,'#f7e5d0','#8c9ab5','#7184a4');box(4.35,4.65,.56,.7,.75,.75,'#fff5e3','#e8dfcc','#d9d2c5');container(4.6,5.7,.56,'#d99ba3');container(4.6,6.5,.56,'#dabd74');container(4.6,6.5,1.11,'#98bcb9');
// Quayside crane and lifting hook.
box(8.15,7,.16,.45,.45,2.5,'#efcb83','#dec18a','#c9a66a');box(6.9,7,2.62,2.6,.3,.25,'#f3d995','#dfbb74','#d3ac63');box(7.1,7.09,1.5,.035,.035,1.14,'#7f8a98','#7f8a98','#7f8a98');box(7,7.04,1.4,.24,.12,.12,'#727d8c','#727d8c','#727d8c')}
function highlightIfCurrent(x,z,i){if(i!==teams[turn].pos)return;ctx.strokeStyle=teams[turn].color;ctx.lineWidth=2;ctx.beginPath();[[x,z,.36],[x+3,z,.36],[x+3,z+3,.36],[x,z+3,.36]].forEach((p,j)=>{const v=project(...p);j?ctx.lineTo(...v):ctx.moveTo(...v)});ctx.closePath();ctx.stroke()}
function seenBadge(x,z){const q=project(x+2.55,z+.45,.5);ctx.fillStyle='#00000055';ctx.beginPath();ctx.arc(q[0],q[1],unit*.26,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff';ctx.font=`bold ${Math.max(9,unit*.28)}px Segoe UI`;ctx.textAlign='center';ctx.fillText('✔',q[0],q[1]+unit*.1)}
function innerStripe(x,z,i,color){const leg=Math.floor(i/5);if(leg===0)box(x+.13,z+2.51,.345,2.72,.34,.03,color,color,color);else if(leg===2)box(x+.13,z+.13,.345,2.72,.34,.03,color,color,color);else if(leg===1)box(x+.13,z+.13,.345,.34,2.72,.03,color,color,color);else box(x+2.51,z+.13,.345,.34,2.72,.03,color,color,color)}
function specialTile(x,z,i,type){const bg=CORNER_INFO[type].bg;box(x+.05,z+.05,0,2.88,2.88,.3,bg,'#8d9a95','#7c8d88');box(x+.13,z+.13,.3,2.72,2.72,.04,'#faf7ee','#ebe5d9','#d4d6cc');const q=project(x+1.5,z+1.5,.38);ctx.textAlign='center';if(type==='jail'){jailIcon(q[0],q[1]-unit*.4,unit*1.1)}else{ctx.font=`${unit*1.05}px Segoe UI`;ctx.fillText(CORNER_INFO[type].icon,q[0],q[1]-unit*.05)}ctx.fillStyle='#4a4438';ctx.font=`700 ${Math.max(9,unit*.25)}px Segoe UI`;ctx.fillText(CORNER_INFO[type].label,q[0],q[1]+unit*.8);highlightIfCurrent(x,z,i)}
function vocabTile(x,z,i){const c=['#e4b2ba','#b5cce7','#ead6a4','#b4d9c7'][Math.floor(i/5)];box(x+.05,z+.05,0,2.88,2.88,.3,c,'#b8b9c5','#a6acb7');box(x+.13,z+.13,.3,2.72,2.72,.04,'#faf7ee','#ebe5d9','#d4d6cc');innerStripe(x,z,i,c);const q=project(x+1.5,z+1.5,.38);ctx.textAlign='center';ctx.fillStyle='#625b75';ctx.font=`800 ${Math.max(16,unit*.75)}px Segoe UI`;ctx.fillText(String(vocabIndexAt[i]+1).padStart(2,'0'),q[0],q[1]);if(seen.has(i))seenBadge(x,z);highlightIfCurrent(x,z,i)}
function draw(){ctx.clearRect(0,0,width,height);const shadow=project(9,9,-.9);ctx.fillStyle='#738ba622';ctx.beginPath();ctx.ellipse(...shadow,unit*17.3,unit*8.85,0,0,Math.PI*2);ctx.fill();box(-.16,-.16,-.55,18.32,18.32,.55,'#dce4da','#b9c8c0','#a8bbb8');const HS=4/3,savedUnit=unit,savedOy=oy;unit=savedUnit*HS;oy=savedOy-1.02*savedUnit;harbor();unit=savedUnit;oy=savedOy;path.map(([x,z],i)=>({x,z,i})).sort((a,b)=>(a.x+a.z)-(b.x+b.z)).forEach(({x,z,i})=>{const type=CORNER_TYPES[i];if(type)specialTile(x,z,i,type);else vocabTile(x,z,i)});teams.map((t,i)=>({t,i})).sort((a,b)=>a.t.point[0]+a.t.point[1]-b.t.point[0]-b.t.point[1]).forEach(({t,i})=>animal(t,i))}
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;canvas.width=width*devicePixelRatio;canvas.height=height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);unit=Math.max(3,Math.min((width-40)/38,(height-40)/24));ox=width/2;oy=height/2-unit*8.4+20;draw()}
new ResizeObserver(resize).observe(canvas);
function update(){const t=teams[turn];document.documentElement.style.setProperty('--team',t.color);$('#team-name').textContent='Team '+t.name;$('#team-avatar').textContent=t.emoji;$('#team-dot').style.background=t.color;$('#round').textContent=round;$('#scoreboard').innerHTML=teams.map((t,i)=>`<div class="team-score ${i===turn?'active':''}" style="--color:${t.color}"><div class="score-name">${t.emoji} ${t.name}</div><strong>${t.score}</strong><small>points</small><span class="turn-label">${i===turn?'Playing':tileLabel(t.pos)}</span></div>`).join('');draw()}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
function stepMove(t,token){const old=path[t.pos];t.pos=(t.pos+1)%path.length;const dest=path[t.pos],start=performance.now();return new Promise(resolve=>{function frame(now){if(token!==epoch){resolve();return}const n=Math.min(1,(now-start)/230);t.point=[old[0]+(dest[0]-old[0])*n,old[1]+(dest[1]-old[1])*n];hop=Math.sin(n*Math.PI)*.75;draw();if(n<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)})}
async function roll(){if(phase!=='ready')return;phase='moving';const token=epoch,t=teams[turn];$('#roll').disabled=true;$('#phase').textContent='ROLLING THE DICE';const dice=$('#dice');dice.classList.add('rolling');lastRoll=random(6)+1;for(let i=0;i<9;i++){dice.textContent=DICE[random(6)];await delay(60);if(epoch!==token)return}dice.classList.remove('rolling');dice.textContent=DICE[lastRoll-1];$('#phase').textContent=`TEAM ${t.name.toUpperCase()} MOVES ${lastRoll} TILES`;for(let i=0;i<lastRoll;i++){await stepMove(t,token);if(token!==epoch)return}
if(round===1&&isVocabTile(t.pos)&&seen.has(t.pos)){$('#phase').textContent='THIS TILE WAS ANSWERED BY ANOTHER TEAM, MOVING ON...';while(!isVocabTile(t.pos)||seen.has(t.pos)){await stepMove(t,token);if(token!==epoch)return}}
hop=0;landTile();update()}
function landTile(){const t=teams[turn],pos=t.pos,type=CORNER_TYPES[pos];if(type){cornerEffect(type);return}if(round>=2&&seen.has(pos)){loseTurn(vocab[vocabIndexAt[pos]]);return}promptQuestion()}
function promptQuestion(){phase='prompt';const t=teams[turn],pos=t.pos;setInline();$('#roll').classList.add('hidden');$('#answers').replaceChildren();$('#next').classList.add('hidden');$('#content').replaceChildren();const icon=document.createElement('div');icon.className='question-emoji';icon.textContent=t.emoji;const h=document.createElement('h2');h.textContent='Question tile!';const p=document.createElement('p');p.textContent=`Team ${t.name}, tap the button below when you are ready to see the question.`;$('#content').append(icon,h,p);$('#phase').textContent='QUESTION READY';$('#tile-tag').textContent=`${tileLabel(pos)} · Roll ${lastRoll}`;$('#show-question').classList.remove('hidden');$('#show-question').focus();$('#keyhint').textContent='Press Enter to show the question'}
function finishTurn(title,icon,text){phase='result';const t=teams[turn];$('#roll').classList.add('hidden');$('#answers').replaceChildren();$('#content').replaceChildren();const iconEl=document.createElement('div');iconEl.className='question-emoji';iconEl.textContent=icon;const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.className='result';p.textContent=text;$('#content').append(iconEl,h,p);$('#phase').textContent=title;$('#tile-tag').textContent=tileLabel(t.pos);$('#next').textContent=`Next up: Team ${teams[(turn+1)%4].name} →`;$('#next').classList.remove('hidden');$('#keyhint').textContent='Press Enter to switch teams';update();setInline();$('#next').focus()}
function cornerEffect(type){const t=teams[turn];if(type==='bonus')t.score+=10;if(type==='penalty')t.score=Math.max(0,t.score-10);const texts={start:`Team ${t.name} passes the Start tile. No points gained or lost.`,bonus:`Team ${t.name} got lucky and gains 10 points!`,jail:`Team ${t.name} is thrown in jail and loses this turn.`,penalty:`Team ${t.name} hit bad luck and loses 10 points.`};finishTurn(CORNER_INFO[type].label,type==='jail'?'🔒':CORNER_INFO[type].icon,texts[type])}
function loseTurn(item){const t=teams[turn];finishTurn('TURN LOST','⏭️',`"${item.term}" was already answered by another team. Team ${t.name} loses this turn.`)}
function question(){phase='question';const t=teams[turn],item=vocab[vocabIndexAt[t.pos]];seen.add(t.pos);choices=shuffle([item.meaning,...shuffle([...new Set(vocab.filter(v=>v.meaning!==item.meaning).map(v=>v.meaning))]).slice(0,2)]);correctIndex=choices.indexOf(item.meaning);$('#phase').textContent='WHAT DOES THIS WORD MEAN?';$('#tile-tag').textContent=`${tileLabel(t.pos)} · Roll ${lastRoll}`;$('#content').replaceChildren();const icon=document.createElement('div');icon.className='question-emoji';icon.textContent=t.emoji;const h=document.createElement('h2');h.textContent=item.term;const p=document.createElement('p');p.textContent=`Team ${t.name}, choose the correct Vietnamese meaning`;$('#content').append(icon,h,p);$('#roll').classList.add('hidden');$('#show-question').classList.add('hidden');$('#answers').replaceChildren();choices.forEach((s,i)=>{const b=document.createElement('button');b.className='answer';const n=document.createElement('b');n.textContent=String(i+1);const text=document.createElement('span');text.textContent=s;b.append(n,text);b.onclick=()=>answer(i);$('#answers').append(b)});setModal();$('#answers button').focus();$('#keyhint').textContent='Choose an answer with key 1, 2 or 3'}
function answer(i){if(phase!=='question'||!Number.isInteger(i)||i<0||i>2)return;phase='result';const t=teams[turn],item=vocab[vocabIndexAt[t.pos]],correct=i===correctIndex;if(correct)t.score+=10;[...$('#answers').children].forEach((b,j)=>{b.disabled=true;if(j===correctIndex)b.classList.add('correct');else if(j===i)b.classList.add('wrong')});const p=document.createElement('p');p.className='result';p.textContent=correct?`Correct! Team ${t.name} +10 points.`:`Not quite. +0 points. Answer: ${item.meaning}`;const def=document.createElement('p');def.className='definition';def.textContent=item.definition;$('#content').append(p,def);$('#phase').textContent=correct?'POINTS FOR YOUR TEAM!':'REMEMBER FOR NEXT TIME';$('#next').textContent=`Next up: Team ${teams[(turn+1)%4].name} →`;$('#next').classList.remove('hidden');$('#keyhint').textContent='Press Enter to continue';update();$('#next').focus()}
function ready(){phase='ready';const t=teams[turn];$('#content').innerHTML=`<div class="dice" id="dice">⚄</div><h2>Is Team ${t.name} ready?</h2><p>Roll the dice, choose the correct meaning, and score 10 points for your team.</p>`;$('#answers').replaceChildren();$('#roll').classList.remove('hidden');$('#roll').disabled=false;$('#show-question').classList.add('hidden');$('#next').classList.add('hidden');$('#phase').textContent="TEAM "+t.name.toUpperCase()+"'S TURN";$('#tile-tag').textContent=tileLabel(t.pos);$('#keyhint').textContent='Press Space to roll · 1–3 to choose';update();setInline()}
function next(){if(phase!=='result')return;turn=(turn+1)%4;if(turn===0)round++;ready();$('#roll').focus()}
$('#roll').onclick=roll;$('#show-question').onclick=question;$('#next').onclick=next;$('#reset').onclick=()=>{if(!confirm('Restart from the beginning? Scores and positions for all 4 teams will be reset.'))return;epoch++;teams.forEach(t=>{t.score=0;t.pos=0;t.point=[0,0]});turn=0;round=1;hop=0;seen.clear();ready()};$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=$('#start').onclick=()=>$('#help-dialog').close();document.addEventListener('keydown',e=>{if($('#help-dialog').open||e.repeat)return;if(e.code==='Space'&&phase==='ready'){e.preventDefault();roll()}else if(['1','2','3'].includes(e.key)&&phase==='question'){e.preventDefault();answer(Number(e.key)-1)}else if(e.key==='Enter'&&phase==='prompt'&&e.target!==$('#show-question')){e.preventDefault();question()}else if(e.key==='Enter'&&phase==='result'&&e.target!==$('#next')){e.preventDefault();next()}});
const getState=()=>({phase,activeTeam:teams[turn].name,round,lastRoll,teams:teams.map(t=>({name:t.name,score:t.score,tile:t.pos+1})),term:phase==='question'?vocab[vocabIndexAt[teams[turn].pos]].term:null,options:phase==='question'?[...choices]:[],wordCount:vocab.length});
window.vocabGame={getState,roll,answer,next};
if(document.modelContext?.registerTool){const result=()=>({content:[{type:'text',text:JSON.stringify(getState())}]});const registrations=[{name:'roll_dice',description:'Roll and move the current team 1–6 tiles.',inputSchema:{type:'object',properties:{}},execute:async()=>{if(phase!=='ready')throw new Error('Complete the current turn first');await roll();return result()}},{name:'answer_vocabulary',description:'Choose option 1–3 and award the current team 10 points if correct.',inputSchema:{type:'object',properties:{option:{type:'integer',minimum:1,maximum:3}},required:['option']},execute:async({option})=>{if(phase!=='question'||!Number.isInteger(option)||option<1||option>3)throw new Error('Choose option 1–3 during a question');answer(option-1);return result()}},{name:'next_team',description:'Finish the answered question and switch to the next team.',inputSchema:{type:'object',properties:{}},execute:async()=>{if(phase!=='result')throw new Error('Answer first');next();return result()}}];for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool({...tool,annotations:{readOnlyHint:false}})).catch(()=>{})}catch{}}}
ready();resize();
})();
